mapper.select:
SELECT pk_id, id, tenant_id, account_id, mobile, code_hash, expire_at, consumed_at,
       is_deleted, gmt_created, gmt_modified, gmt_deleted
FROM mobile_otp
WHERE tenant_id = #{tenantId}
  AND account_id = #{accountId}
  AND mobile = #{mobile}
  AND consumed_at IS NULL
  AND is_deleted = 0
ORDER BY gmt_created DESC
LIMIT 1

SELECT pk_id, id, tenant_id, account_id, mobile, code_hash, expire_at, consumed_at,
       is_deleted, gmt_created, gmt_modified, gmt_deleted
FROM mobile_otp
WHERE tenant_id = #{tenantId}
  AND account_id = #{accountId}
  AND mobile = #{mobile}
  AND is_deleted = 0
ORDER BY gmt_created DESC
LIMIT 1

SELECT COUNT(1) FROM mobile_otp
WHERE tenant_id = #{tenantId}
  AND mobile = #{mobile}
  AND is_deleted = 0
  AND gmt_created >= #{since}
